effect.shader:
float pixelHash(vec2 pixel) {
vec3 p3 = fract(vec3(pixel.xyx) * 0.1031);
p3 += dot(p3, p3.yzx + 33.33);
return fract((p3.x + p3.y) * p3.z);
}
void main() {
vec4 source = texture2DCv(inputImg.texture, acScreenNorm);
float coverage = step(pixelHash(floor(gl_FragCoord.xy)), clamp(source.a, 0.0, 1.0));
gl_FragColor = vec4(source.rgb * coverage, coverage);
}
